<script lang="ts">import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {workspace,createProject,deploy} from '$lib/stores/workspace';import {slugify} from '$lib/model';import {goto} from '$app/navigation';let name='',image='nginx:alpine',domain='',error='',source='';let change=false,choose=false;let fileInput:HTMLInputElement,folderInput:HTMLInputElement;function selected(list:FileList|null){if(list?.length){source=list.length===1?list[0].name:list.length+' files selected';name=slugify(list[0].webkitRelativePath?.split('/')[0]||list[0].name.replace(/\.zip$/i,''));}choose=false;}async function submit(){try{error='';if(!image.trim())throw Error('Enter an image reference.');const id=createProject(name,image,domain);deploy(id,image);await goto('/projects/'+id+'/deployments');}catch(e){error=e instanceof Error?e.message:'Could not create project.';}}</script><Heading title="New project" subtitle="Choose your application source."/><div class="stack" style="max-width:850px"><section class="card"><div class="section-title"><h3>Upload your application</h3><p class="subtitle">Source selection migration preview</p></div><div class="upload-drop"><span class="icon-box"><Icon name="Upload"/></span><h3>Choose your project files</h3><p class="subtitle">Select files or a folder from your computer.</p><div class="upload14-actions"><button class="btn primary" on:click={()=>choose=!choose}>Upload from computer <span class="upload14-chevron">⌄</span></button>{#if choose}<div class="upload14-menu"><button on:click={()=>fileInput.click()}><Icon name="File"/>Files or ZIP archive</button><button on:click={()=>folderInput.click()}><Icon name="Projects"/>Project folder</button></div>{/if}</div><input hidden type="file" multiple bind:this={fileInput} on:change={()=>selected(fileInput.files)}/><input hidden type="file" multiple {...{webkitdirectory: ""}} bind:this={folderInput} on:change={()=>selected(folderInput.files)}/>{#if source}<p class="native-note">{source} · selected locally, not uploaded or analyzed.</p>{/if}</div><div class="native-note"><a class="choice" href="/reference/v016.html" target="_blank" rel="noopener" style="text-decoration:none"><Icon name="Storage"/><span><strong>Use existing files</strong><small>Explore the original File Manager and source inspection prototype.</small></span><Icon name="External"/></a></div><p class="subtitle native-note">ZIP inspection, folder analysis and Git builds remain in the migration backlog. Use the image workflow below for the first native deployment simulation.</p></section><form class="card stack" on:submit|preventDefault={submit}><div><h3>Deploy a container image</h3><p class="subtitle">Milestone 01 preview · no Docker operations performed.</p></div><label class="field">Project name<input required bind:value={name} placeholder="my-application"/></label><label class="field">Container image<input required bind:value={image} placeholder="nginx:alpine"/><small>Example image reference only.</small></label><div class="well"><div class="row between"><span class="strong">Deployment address</span><button class="btn ghost small" type="button" on:click={()=>change=!change}>{change?'Close':'Change'}</button></div><div class="strong native-path">{domain||((slugify(name)||'my-project')+'.drevanta.example')}</div><small>Automatically assigned unless you choose a workspace domain.</small>{#if change}<label class="field native-note">Available address<select bind:value={domain}><option value="">Automatic address</option>{#each $workspace.domains.filter(d=>!d.project) as d}<option value={d.id}>{d.name}</option>{/each}</select></label>{/if}</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><a class="btn secondary" href="/projects">Cancel</a><button class="btn primary" type="submit">Simulate deployment</button></div></form></div>
